import React, { useEffect, useMemo, useRef, useState } from 'react';
import { useDebouncedValue } from '../hooks/useDebouncedValue';
import { useCancelable } from '../hooks/useCancelable';
import { searchAll } from '../services/api';
import reactHooks from 'eslint-plugin-react-hooks';
/**
 * SearchBarUnified
 *
 * Modos:
 * - GLOBAL (default): usa searchAll() y muestra dropdown.
 * - LOCAL/SCOPED: si pasás `scopeItems` (array), NO consulta API. Filtra localmente y
 *   devuelve el resultado por `onScopedChange(filtered, term)`. El panel se puede ocultar con showPanel={false}.
 *
 * Props:
 * - placeholder?: string
 * - scopeItems?: any[]                 // activa modo local si existe
 * - onScopedChange?: (items, term) => void
 * - showPanel?: boolean                // default true (para global). En local suele ir false.
 * - className?: string
 */
export default function SearchBarUnified({
  placeholder = 'Buscar productos, categorías y negocios',
  scopeItems,
  onScopedChange,
  showPanel = true,
  className = '',
}) {
  const [q, setQ] = useState('');
  const debounced = useDebouncedValue(q, 250);
  const { controller } = useCancelable();
  const [combined, setCombined] = useState([]);

  // --- Normalizador para filtro local
  const norm = (s) =>
    String(s || '')
      .toLowerCase()
      .normalize('NFD')
      .replace(/\p{Diacritic}/gu, '');

  const filterLocal = useMemo(() => {
    if (!Array.isArray(scopeItems)) return () => [];
    return (term) => {
      const t = norm(term).trim();
      if (!t) return scopeItems;
      return scopeItems.filter((p) => {
        const name = norm(p?.name);
        const desc = norm(p?.description);
        const seller = norm(p?.seller?.name);
        return name.includes(t) || desc.includes(t) || seller.includes(t);
      });
    };
  }, [scopeItems]);

  // ====== MODO LOCAL (SCOPED) ======
  // Evitamos loops: no tocamos `combined` y sólo notificamos cambios reales
  const lastLocalSigRef = useRef('');
  useEffect(() => {
    if (!Array.isArray(scopeItems)) return; // no es modo local

    const filtered = filterLocal(debounced);
    // firma barata del resultado: length + primeros ids
    const sig =
      (debounced || '') +
      '|' +
      filtered.length +
      '|' +
      filtered.slice(0, 5).map((x) => x?.id).join(',');

    if (sig !== lastLocalSigRef.current) {
      lastLocalSigRef.current = sig;
      if (typeof onScopedChange === 'function') onScopedChange(filtered, debounced);
    }
    // ⚠️ Importante: NO setCombined([]) aquí para no re-renderizar en bucle
  }, [debounced, scopeItems, filterLocal, onScopedChange]);

  // ====== MODO GLOBAL ======
  useEffect(() => {
    if (Array.isArray(scopeItems)) return; // si es local, no disparamos global

    // limpiar resultados si la query está vacía
    if (!debounced.trim()) {
      // sólo si había algo cargado, para evitar renders innecesarios
      if (combined.length) setCombined([]);
      return;
    }

    (async () => {
      try {
        const ac = controller(); // AbortController por búsqueda
        const data = await searchAll(debounced, ac);
        const cap = 8;
        const p = data.products || [];
        const c = data.categories || [];
        const s = data.sellers || [];
        const arr = [];
        for (const it of p) { if (arr.length < cap) arr.push({ type: 'product', ...it }); }
        for (const it of c) { if (arr.length < cap) arr.push({ type: 'category', ...it }); }
        for (const it of s) { if (arr.length < cap) arr.push({ type: 'seller', ...it }); }
        setCombined(arr);
      } catch {
        /* ignore cancels */
      }
    })();
    // deps: SOLO lo que cambia la búsqueda global
    // (no incluimos `controller` para que no se regenere el efecto por identidad)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [debounced, scopeItems]); // scopeItems en deps para salir de global si cambia a local

  const onSubmit = (e) => {
    e.preventDefault();
  };

  return (
    <form className={`cp-search-wrap ${className}`} onSubmit={onSubmit}>
      <input
        className="cp-search-input"
        placeholder={placeholder}
        value={q}
        onChange={(e) => setQ(e.target.value)}
        type="search"
        aria-label="Buscar"
      />
      {/* Botón lupa sólo visual */}
      <button className="cp-search-btn" type="submit" aria-label="Buscar">
        <svg width="18" height="18" viewBox="0 0 24 24" aria-hidden="true">
          <path
            d="M21 21l-4.35-4.35m1.35-5.65a7 7 0 11-14 0 7 7 0 0114 0z"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
          />
        </svg>
      </button>

      {/* Panel de resultados sólo en GLOBAL (o si showPanel === true explícito) */}
      {showPanel && !!combined.length && !Array.isArray(scopeItems) && (
        <div className="cp-search-panel">
          {combined.map((item) => (
            <a
              key={`${item.type}-${item.id}`}
              href={
                item.type === 'product'
                  ? `/producto/${item.id}`
                  : item.type === 'category'
                  ? `/categoria/${item.id}`
                  : `/negocio/${item.id}`
              }
              className="cp-search-item"
            >
              <img
                className="thumb"
                src={item.imageUrl || item.image || '/placeholder.png'}
                alt=""
              />
              <span
                className={
                  item.type === 'category' ? 'b' : item.type === 'seller' ? 'i' : ''
                }
              >
                {item.name}
              </span>
            </a>
          ))}
        </div>
      )}

      {/* estilos mínimos del control */}
      <style>{`
        .cp-search-wrap{
          position:relative; width:100%;
          display:flex; align-items:center;
          background:#fff;
          border:2px solid #F7D34A;
          border-radius:999px;
          padding:6px;
          box-shadow:0 4px 18px rgba(0,0,0,.1);
          gap:6px;
        }
        .cp-search-input{
          flex:1; border:0; outline:none; background:transparent;
          font-size:14px; padding:8px 10px; color:#111;
        }
        .cp-search-btn{
          display:grid; place-items:center;
          border:0; outline:none; cursor:pointer;
          background:#F7D34A; color:#000; border-radius:999px;
          width:38px; height:38px;
          transition:transform .08s ease, box-shadow .15s ease;
        }
        .cp-search-btn:hover{ transform:translateY(-1px); box-shadow:0 6px 14px rgba(0,0,0,.18); }
        .cp-search-btn:active{ transform:translateY(0); box-shadow:none; }

        .cp-search-panel{
          position:absolute; left:0; right:0; top:calc(100% + 8px);
          background:#fff; border:1px solid #ececec; border-radius:14px;
          box-shadow:0 14px 32px rgba(0,0,0,.18); overflow:hidden; z-index:5;
          max-height:340px; overflow-y:auto;
        }
        .cp-search-item{
          display:flex; align-items:center; gap:10px;
          padding:10px 12px; text-decoration:none; color:#111;
        }
        .cp-search-item:hover{ background:#fafafa; }
        .cp-search-item .thumb{
          width:42px; height:32px; object-fit:cover;
          border-radius:6px; border:1px solid #eee; background:#f6f6f6;
        }
        .cp-search-item .b{ font-weight:700; }
        .cp-search-item .i{ font-style:italic; }
      `}</style>
    </form>
  );
}
